-- Fakt kartochkalari orqa tomonining ruscha matni — 70-partiya:
-- Muqimiy, Najmiddin Kubro, Odil Yoqubov.

UPDATE fact_cards SET detail_ru = 'Мукими (псевдоним; настоящее имя — Мухаммад Аминходжа, сын Мирзаходжи) родился в 1850 году в Коканде. Отец его был из Ташкента, мать Айшабиби — из Худжанда, а семья жила в Коканде. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1916;
UPDATE fact_cards SET detail_ru = 'Влечение к поэзии пробудила в Мукими его мать Айшабиби. Поэт учился у Навои, Джами, Низами и Физули, а Джами принял себе в наставники. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1917;
UPDATE fact_cards SET detail_ru = 'Начальное образование Мукими получил в махаллинской школе, затем учился в медресе «Мохлар ойим», построенном Надирой, и в бухарских медресе (1864–1865; 1875–1876). Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1918;
UPDATE fact_cards SET detail_ru = 'В 1876 году Мукими вернулся в Коканд и служил писцом в землеустроительной управе. В конце 1870-х годов он начал заниматься творчеством. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1919;
UPDATE fact_cards SET detail_ru = 'После смерти отца положение Мукими стало тяжёлым, и в 1885 году он переселился в маленькую келью медресе «Хазрат». Вся жизнь поэта прошла в бедности. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1920;
UPDATE fact_cards SET detail_ru = 'Мукими создал около тридцати сатирических сочинений, таких как «Танобчилар», «Выборы», «В порицание времени», «Я безумец», «Я бедняк», «Мухи», «Жалоба на украшательство». В его обличительных сочинениях раскрыты дела царских чиновников и местных богачей. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1921;
UPDATE fact_cards SET detail_ru = '«Путевые записки» — сочинение из четырёх частей, написанное лёгким, игривым размером и составленное из четверостиший. В нём правдиво изображены тяжесть народной жизни и разорение селений. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1922;
UPDATE fact_cards SET detail_ru = 'В 1887–1888 и в 1892 годах Мукими совершил поездки в Ташкент и глубоко изучил культурную и литературную жизнь города. Он завязал связи с такими передовыми по духу сочинителями, как Алмаи и Надим, и работал с ними сообща. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1923;
UPDATE fact_cards SET detail_ru = 'Мукими ввёл в узбекскую словесность рабочую тему и создал такие сочинения, как «О московском бае» и «Происшествие с Виктором». Его лирика напитана глубоким жизнелюбием и внесла в узбекскую словесность такие ценности, как дружба, верность и искренность. Мукими вместе с Фуркатом, Завки, Авазом и Комилом числится в ряду поэтов передовой мысли. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1924;
UPDATE fact_cards SET detail_ru = 'Мукими умер 25 мая 1903 года в Коканде. После его смерти, в 1907 году, Остроумов издал сборник «Диван Мукими», а в 1910 и 1912 годах был напечатан «Диван Мукими с сатирами»; сохранились десять стихотворных и около двадцати прозаических писем поэта. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1925;

UPDATE fact_cards SET detail_ru = 'Наджмиддин Кубро родился в 1145 году в нынешнем селении Саят близ Хивы. Он известен как знаменитый шейх, крупный учёный суфизма, народный герой и пламенный поэт. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1897;
UPDATE fact_cards SET detail_ru = 'Полное его имя — Ахмад ибн Умар Абульджаннаб Наджмиддин аль-Кубра аль-Хиваки аль-Хорезми. Прозвище «шейх валитарош» означает «шейх, взращивающий святых». Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1898;
UPDATE fact_cards SET detail_ru = 'Наджмиддин Кубра положил начало известному в суфизме пути кубравия. Приверженцы этого пути проповедовали тайное поминание, а учение кубравия разошлось в основном по Средней Азии и отчасти по Ирану. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1899;
UPDATE fact_cards SET detail_ru = 'Науке известно около десяти сочинений Наджмиддина Кубры. Особенно известны книги «Аль-усуль аль-ашара» («Десять правил»), «Фавоих уль-джамол ва фавотих уль-джалол» («Благоухания красоты и откровения величия»), «Рисалат уль-хоиф уль-хоим ан лавмат иль-лоим», «Тафсир» и «Шарх ус-сунна ва-ль-масолик». Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1900;
UPDATE fact_cards SET detail_ru = 'Кубра писал свои сочинения в основном по-арабски и лишь сочинение «Фи одоб ус-соликин» («О благонравии идущих по пути») и свои рубаи написал на персидском. Английский востоковед Дж. С. Тримингэм отмечает, что сочинение «О благонравии идущих по пути» стало важной ступенью в иранизации суфизма. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1901;
UPDATE fact_cards SET detail_ru = 'До сего дня известны двадцать шесть рубаи, принадлежащих творчеству Наджмиддина Кубры: востоковед Е. Э. Бертельс привёл в книге «Суфизм и суфийская литература» двадцать пять рубаи, отобранных им из разных тазкире и баязов, а из восьми рубаи в сборнике «Рубаинаме», изданном в Иране, одно среди них не встречается. Эти рубаи переложили на узбекский Джамал Камал и Матназар Абдулхаким. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1902;
UPDATE fact_cards SET detail_ru = 'Когда монгольские полчища вторглись на землю Хорезма, Наджмиддин Кубра, не желая, чтобы его ученики из других краёв погибли на чужой земле, отправил их на родину. А сам он вышел на защиту города. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1903;
UPDATE fact_cards SET detail_ru = 'На предложения учеников уйти вместе с ними Наджмиддин Кубра ответил: «Я приму здесь мученическую смерть. Мне не дозволено покинуть Хорезм!» Он взял в руку меч, наполнил полы камнями и вышел навстречу врагу, бросал в неприятеля камни и нескольких сразил копьём. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1904;
UPDATE fact_cards SET detail_ru = 'Наджмиддин Кубра погиб в 1221 году при защите города от монголов. В минуту гибели он вырвал у врага знамя и сжал его так крепко, что даже вдесятером не смогли вынуть знамя из его руки и вынуждены были отсечь ему пальцы. Источник: Ziyouz.com, раздел «Персидско-таджикская поэзия».' WHERE id = 1905;

UPDATE fact_cards SET detail_ru = 'Адыл Якубов родился 20 октября 1926 года в селении Карнак нынешней Южно-Казахстанской области. Позже он стал одним из крупных писателей узбекской словесности. Источник: Ziyouz.com.' WHERE id = 2243;
UPDATE fact_cards SET detail_ru = 'В 1956 году Адыл Якубов окончил филологический факультет Ташкентского государственного университета. Эти знания стали ему основанием на писательском пути. Источник: Ziyouz.com.' WHERE id = 2244;
UPDATE fact_cards SET detail_ru = 'Первое его сочинение — повесть «Ровесники» — было издано в 1951 году. Затем вышли такие его сочинения, как «Первый шаг» (1953), «Мукаддас» (1960). Источник: Ziyouz.com.' WHERE id = 2245;
UPDATE fact_cards SET detail_ru = 'Роман «Сокровище Улугбека» был издан в 1973 году и является одним из самых известных сочинений Адыла Якубова. В 1982 году вышел и роман писателя «Древний мир». Источник: Ziyouz.com.' WHERE id = 2246;
UPDATE fact_cards SET detail_ru = 'Роман «Совесть» вышел в 1977 году. Писатель создал также романы «Если беда придёт на голову мужа…» (1966), «Сокровище Улугбека» (1973), «Древний мир» (1982), «Лебеди, белые птицы» (1988) и «Обитель справедливости» (1998). Источник: Ziyouz.com.' WHERE id = 2247;
UPDATE fact_cards SET detail_ru = 'В 1977 году он стал лауреатом Государственной премии имени Хамзы, в 1985-м получил звание народного писателя Узбекистана. В 1994 году он был награждён орденом «Дустлик», а в 1998-м — орденом «Эл-юрт хурмати». Источник: Ziyouz.com.' WHERE id = 2248;
UPDATE fact_cards SET detail_ru = 'Адыл Якубов умер 21 декабря 2009 года в Ташкенте. Он оставил в узбекской словесности богатое творческое наследие. Источник: Ziyouz.com.' WHERE id = 2249;
